from __future__ import annotations

"""Compact App Ready pipeline monitor for the Mobile V1 Data page."""

_STYLE='''<style id="yipmanAppReadyStatusStyle">#appReadyMonitor{border:1px solid #314252;border-radius:18px;background:#141d26;padding:14px;margin:0 0 12px}.ar-head{display:flex;justify-content:space-between;gap:10px;align-items:center}.ar-head b{font-size:18px}.ar-state{font-size:10px;font-weight:1000}.ar-bar{height:8px;border-radius:999px;background:#0d141b;overflow:hidden;margin:10px 0}.ar-fill{height:100%;background:#79c890;width:0}.ar-grid{display:grid;grid-template-columns:1fr 1fr;gap:7px}.ar-cell{border:1px solid #293744;border-radius:10px;padding:8px}.ar-cell b{display:block;font-size:7px;color:#8493a1}.ar-cell span{display:block;font-size:11px;font-weight:900;margin-top:3px;overflow-wrap:anywhere}.ar-stages{font-size:9px;color:#8fa0ad;margin-top:9px;line-height:1.5}.ar-error{color:#ff929c}</style>'''
_SCRIPT=r'''<script id="yipmanAppReadyStatusScript">(()=>{'use strict';
const esc=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function host(){let page=document.getElementById('data');if(!page)return null;let h=document.getElementById('appReadyMonitor');if(h)return h;h=document.createElement('div');h.id='appReadyMonitor';const top=page.querySelector('.top');top?.insertAdjacentElement('afterend',h);return h}
function draw(s){const h=host();if(!h)return;const pct=Number(s.progress_pct??(s.app_ready?100:0));const serving=s.active_build_id||'—';const building=s.status==='BUILDING'?s.build_id:'—';const queued=s.rebuild_queued?('YES · '+(s.queued_source||'')):'NO';const err=s.error?'<div class="ar-stages ar-error">'+esc(s.error)+'</div>':'';h.innerHTML='<div class="ar-head"><b>APP READY PIPELINE</b><span class="ar-state">'+esc(s.status||'UNKNOWN')+'</span></div><div class="ar-bar"><div class="ar-fill" style="width:'+Math.max(0,Math.min(100,pct))+'%"></div></div><div class="ar-grid"><div class="ar-cell"><b>PROGRESS</b><span>'+esc(pct)+'%</span></div><div class="ar-cell"><b>STAGE</b><span>'+esc(s.stage)+'</span></div><div class="ar-cell"><b>SERVING SNAPSHOT</b><span>'+esc(serving)+'</span></div><div class="ar-cell"><b>BUILDING SNAPSHOT</b><span>'+esc(building)+'</span></div><div class="ar-cell"><b>DATA THROUGH</b><span>'+esc(s.active_data_through||s.data_through)+'</span></div><div class="ar-cell"><b>QUEUED REFRESH</b><span>'+esc(queued)+'</span></div></div><div class="ar-stages">PUBLISH → PRECALCULATE → PREANALYZE → BUILD SNAPSHOT → APP READY<br>Sections '+esc(s.sections_ready)+' / '+esc(s.sections_total)+(s.build_ms!=null?' · Last build '+esc(Math.round(s.build_ms))+' ms':'')+'</div>'+err}
async function refresh(){try{const r=await fetch('/api/yipman/app-ready/status',{cache:'no-store'});if(r.ok)draw(await r.json())}catch(_){const h=host();if(h)h.innerHTML='<div class="ar-head"><b>APP READY PIPELINE</b><span class="ar-state ar-error">STATUS UNAVAILABLE</span></div>'}}
const obs=new MutationObserver(()=>{if(document.getElementById('data')?.classList.contains('active'))refresh()});obs.observe(document.documentElement,{subtree:true,attributes:true,attributeFilter:['class']});setInterval(()=>{if(document.getElementById('data')?.classList.contains('active'))refresh()},5000);})();</script>'''

def polish_app_ready_status_html(html:str)->str:
    if 'yipmanAppReadyStatusScript' in html:return html
    return html.replace('</head>',_STYLE+'</head>',1).replace('</body>',_SCRIPT+'</body>',1)
